CREATE TABLE IF NOT EXISTS schema_version (version INT NOT NULL PRIMARY KEY, applied_at INT NOT NULL);

CREATE TABLE IF NOT EXISTS users (
id INTEGER PRIMARY KEY AUTOINCREMENT,
username TEXT NOT NULL UNIQUE,
pass_hash VARCHAR(255) NOT NULL,
created_at INT NOT NULL
        );

CREATE TABLE IF NOT EXISTS rockstars (
id INTEGER PRIMARY KEY AUTOINCREMENT,
user_id INTEGER NOT NULL UNIQUE,
stage_name TEXT NOT NULL,
real_name TEXT NOT NULL DEFAULT '',
pronouns VARCHAR(40) NOT NULL DEFAULT 'they/them',
gender VARCHAR(60) NOT NULL DEFAULT 'unsaid',
age INT NOT NULL DEFAULT 21,
hometown VARCHAR(80) NOT NULL DEFAULT '',
bio TEXT,
backstory TEXT NOT NULL,
appearance TEXT NOT NULL,
instrument VARCHAR(20) NOT NULL,
musicianship DOUBLE NOT NULL DEFAULT 10,
vocals DOUBLE NOT NULL DEFAULT 10,
songwriting DOUBLE NOT NULL DEFAULT 10,
stagecraft DOUBLE NOT NULL DEFAULT 10,
charisma DOUBLE NOT NULL DEFAULT 10,
stamina DOUBLE NOT NULL DEFAULT 10,
energy DOUBLE NOT NULL DEFAULT 100,
mood DOUBLE NOT NULL DEFAULT 70,
cash INT NOT NULL DEFAULT 0,
fame INT NOT NULL DEFAULT 0,
fans INT NOT NULL DEFAULT 0,
gigs_played INT NOT NULL DEFAULT 0,
best_wpm INT NOT NULL DEFAULT 0,
last_rest INT NOT NULL DEFAULT 0,
last_tick INT NOT NULL,
created_at INT NOT NULL,
FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS bands (
id INTEGER PRIMARY KEY AUTOINCREMENT,
rockstar_id INTEGER NOT NULL UNIQUE,
name TEXT NOT NULL,
genre VARCHAR(20) NOT NULL,
chemistry DOUBLE NOT NULL DEFAULT 20,
created_at INT NOT NULL,
FOREIGN KEY (rockstar_id) REFERENCES rockstars(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS bandmates (
id INTEGER PRIMARY KEY AUTOINCREMENT,
band_id INTEGER NOT NULL,
name TEXT NOT NULL,
role VARCHAR(20) NOT NULL,
pronouns VARCHAR(40) NOT NULL DEFAULT 'they/them',
personality VARCHAR(20) NOT NULL,
skill DOUBLE NOT NULL,
loyalty DOUBLE NOT NULL DEFAULT 60,
wage INT NOT NULL,
appearance TEXT NOT NULL,
hired_at INT NOT NULL,
FOREIGN KEY (band_id) REFERENCES bands(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS songs (
id INTEGER PRIMARY KEY AUTOINCREMENT,
band_id INTEGER NOT NULL,
title TEXT NOT NULL,
genre VARCHAR(20) NOT NULL,
theme VARCHAR(20) NOT NULL,
bpm INT NOT NULL,
lyrics TEXT NOT NULL,
quality DOUBLE NOT NULL,
tightness DOUBLE NOT NULL DEFAULT 0,
times_played INT NOT NULL DEFAULT 0,
released_at INT,
streams INT NOT NULL DEFAULT 0,
created_at INT NOT NULL,
FOREIGN KEY (band_id) REFERENCES bands(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS gigs (
id INTEGER PRIMARY KEY AUTOINCREMENT,
rockstar_id INTEGER NOT NULL,
venue VARCHAR(20) NOT NULL,
setlist TEXT NOT NULL,
performance DOUBLE NOT NULL,
attendance INT NOT NULL,
earnings INT NOT NULL,
fans_gained INT NOT NULL,
fame_gained INT NOT NULL,
stars INT NOT NULL,
review TEXT NOT NULL,
played_at INT NOT NULL,
FOREIGN KEY (rockstar_id) REFERENCES rockstars(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS wardrobe (
rockstar_id INTEGER NOT NULL,
item VARCHAR(60) NOT NULL,
bought_at INT NOT NULL,
PRIMARY KEY (rockstar_id, item),
FOREIGN KEY (rockstar_id) REFERENCES rockstars(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS news (
id INTEGER PRIMARY KEY AUTOINCREMENT,
rockstar_id INTEGER NOT NULL,
kind VARCHAR(20) NOT NULL,
text TEXT NOT NULL,
created_at INT NOT NULL,
FOREIGN KEY (rockstar_id) REFERENCES rockstars(id) ON DELETE CASCADE
        );

CREATE TABLE IF NOT EXISTS recruit_log (
rockstar_id INTEGER NOT NULL,
day VARCHAR(10) NOT NULL,
slot INT NOT NULL,
PRIMARY KEY (rockstar_id, day, slot)
        );

CREATE INDEX IF NOT EXISTS idx_news ON news (rockstar_id, created_at);

CREATE INDEX IF NOT EXISTS idx_fame ON rockstars (fame);

ALTER TABLE rockstars ADD COLUMN xp INT NOT NULL DEFAULT 0;

ALTER TABLE rockstars ADD COLUMN level INT NOT NULL DEFAULT 1;

ALTER TABLE rockstars ADD COLUMN skill_points INT NOT NULL DEFAULT 0;

ALTER TABLE songs ADD COLUMN learned INT NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS counters (
    rockstar_id INTEGER NOT NULL, ckey VARCHAR(40) NOT NULL, value INT NOT NULL DEFAULT 0,
    PRIMARY KEY (rockstar_id, ckey));

CREATE TABLE IF NOT EXISTS achievements (
    rockstar_id INTEGER NOT NULL, akey VARCHAR(40) NOT NULL, unlocked_at INT NOT NULL,
    PRIMARY KEY (rockstar_id, akey));

CREATE TABLE IF NOT EXISTS daily_goals (
    rockstar_id INTEGER NOT NULL, day VARCHAR(10) NOT NULL, slot INT NOT NULL, gkey VARCHAR(40) NOT NULL,
    target INT NOT NULL, progress INT NOT NULL DEFAULT 0, reward_cash INT NOT NULL, reward_xp INT NOT NULL,
    claimed INT NOT NULL DEFAULT 0, PRIMARY KEY (rockstar_id, day, slot));

CREATE TABLE IF NOT EXISTS login_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ukey VARCHAR(120) NOT NULL, at INT NOT NULL);

CREATE TABLE IF NOT EXISTS follows (
    follower_id INTEGER NOT NULL, followed_id INTEGER NOT NULL, created_at INT NOT NULL,
    PRIMARY KEY (follower_id, followed_id));

CREATE INDEX IF NOT EXISTS idx_login_attempts ON login_attempts (ukey, at);

CREATE INDEX IF NOT EXISTS idx_rockstars_level ON rockstars (level);

CREATE INDEX IF NOT EXISTS idx_rockstars_wpm ON rockstars (best_wpm);

CREATE INDEX IF NOT EXISTS idx_rockstars_gigs ON rockstars (gigs_played);

CREATE TABLE IF NOT EXISTS look_presets (
    rockstar_id INTEGER NOT NULL, slot INT NOT NULL, name VARCHAR(30) NOT NULL, appearance TEXT NOT NULL, saved_at INT NOT NULL,
    PRIMARY KEY (rockstar_id, slot));
